  import org.apache.log4j.Logger;
  import java.util.concurrent.TimeUnit;
  import sailpoint.tools.Util;
  import java.text.SimpleDateFormat;
  import java.util.Date;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Rule-Rehire-LifeCycleEevnt-Trigger");
  log.debug("Alpha-Rule-Rehire-LifeCycleEevnt-Trigger - STARTS");

  boolean shouldTrigger = false;


  if(null != previousIdentity @and null != newIdentity)
  {
    log.debug("oldID"+previousIdentity.toXml());
    log.debug("newID"+newIdentity.toXml());

    String oldStatus = previousIdentity.getAttribute("Status");
    String newStatus = newIdentity.getAttribute("Status");
    String terminationDate = previousIdentity.getAttribute("terminationDate");

    if(null != terminationDate)
    {
      log.debug("oldStatus"+oldStatus);
      log.debug("newStatus"+newStatus);
      log.debug("terminationDate"+terminationDate);

      SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
      Date termDate = sdf.parse(terminationDate);
      Date todaysDate = new Date();

      long diffInMillies = Math.abs(todaysDate.getTime() - termDate.getTime());
      long diff = TimeUnit.DAYS.convert(diffInMillies, TimeUnit.MILLISECONDS);
      log.debug("diff:"+diff);

      if(null != oldStatus @and null != newStatus @and newStatus.equalsIgnoreCase("Active") @and oldStatus.equalsIgnoreCase("InActive") @and diff < 90 )
      {
        shouldTrigger = true;
      }
    }
  }

  log.debug("Alpha-Rule-Rehire-LifeCycleEevnt-Trigger - ENDS");
  return shouldTrigger;
